    [
      ["a", "b", "Up"],
      ["b", "a", "Down"],
      ["a", "c", "Side"],
      ["c", "a", "Back"],
    ],
  );
  const path: PathStep[] = [];
  for (const [from, to] of ["ab", "ba", "ac", "ca"]) {
    let step: Step | undefined;
    for (const t of graph.steps)
      if (t.from === from && t.to === to) {
        step = t;
