    path.push({ action: step.action, state: to, step });
  }
  const loop: Bug = {
    rule: { kind: "property", name: "Settles" },
    start: "a",
    path,
    loop: 0,
    stutters: false,
  };
  const { report } = draw(graph, { state: (v) => v.pos }, [loop]);
  assert.match(report, /^The run loops through "a", "b" and "c" forever\.$/m);
});

